package main

import (
	"database/sql"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl = template.Must(template.New("results").Parse(`
<html><body>
<h2>Product Search</h2>
<form method="GET" action="/search">
  <input name="category" value="{{.Query}}">
  <button>Search</button>
</form>
<table>{{range .Products}}<tr><td>{{.Name}}</td><td>{{.Price}}</td></tr>{{end}}</table>
</body></html>`))

type Product struct {
	Name  string
	Price string
}

type PageData struct {
	Query    string
	Products []Product
}

func initDB() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")

	// Basic input length check
	if len(category) > 100 {
		http.Error(w, "Input too long", http.StatusBadRequest)
		return
	}

	// Reject null bytes
	if strings.Contains(category, "\x00") {
		http.Error(w, "Invalid input", http.StatusBadRequest)
		return
	}

	// Build query - developer intended to use parameterized query but
	// needed ILIKE with dynamic pattern matching
	query := fmt.Sprintf(
		"SELECT name, price::text FROM products WHERE category ILIKE '%%%s%%' AND active = true ORDER BY name LIMIT 50",
		category,
	)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.Name, &p.Price); err != nil {
			continue
		}
		products = append(products, p)
	}

	data := PageData{Query: category, Products: products}
	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, data)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	initDB()
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
